/**
 * Builds the script that hook.js puts into claude.ai pages.
 *
 * The payload cannot `import` anything - it runs in the page as a plain script. So the
 * shared pieces are inlined here, not copied by hand:
 *
 *   @smartrtl/core  the rule      - which direction does this text belong to?
 *   @smartrtl/dom   the engine    - when to ask, and what to do with the answer
 *   src/injected    the adapter   - the parts that are only true of claude.ai
 *
 * Both packages are UMD files: given a fresh local `module`, each hands back its exports.
 * Everything stays inside one closure, so nothing of ours reaches the page's globals except
 * the status function the adapter sets on purpose.
 *
 *   node build/bundle-payload.js
 */
const fs = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "..");
const core = fs.readFileSync(path.resolve(root, "../../packages/core/src/direction.js"), "utf8");
const dom = fs.readFileSync(path.resolve(root, "../../packages/dom/src/engine.js"), "utf8");
const payload = fs.readFileSync(path.join(root, "src/injected/payload.js"), "utf8");
const outPath = path.join(root, "dist/payload.js");

const BEGIN = "/* ==== smart-rtl-direction patch BEGIN ==== */";
const END = "/* ==== smart-rtl-direction patch END ==== */";

// The adapter must go through the engine, and the engine through the rule. If that wiring
// is ever lost, the build fails here rather than ship logic that has drifted from the
// other surfaces.
if (!payload.includes("SmartRTLDom.start(SmartRTL")) throw new Error("the adapter does not hand the shared rule to the shared engine");
if (!dom.includes("rule.openingLetters")) throw new Error("the engine does not use the shared rule");

const out = [
  BEGIN,
  "/* generated by build/bundle-payload.js - edit src/injected/payload.js instead */",
  ";(function () {",
  '  "use strict";',
  "  var module = { exports: {} };",
  core.trim(),
  "  var SmartRTL = module.exports;",
  "  module = { exports: {} };",
  dom.trim(),
  "  var SmartRTLDom = module.exports;",
  payload.replace(BEGIN, "").replace(END, "").trim(),
  "})();",
  END,
  "",
].join("\n");

new Function(out); // parse check: a broken payload must never reach the app
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, out, "utf8");
console.log(`dist/payload.js ${out.length} bytes`);
